fn all_in(text: Str, alphabet: Str) -> Bool {
  if text.is_empty() {
    return false
  }
  for c in text.chars() {
    if not alphabet.contains(c) {
      return false
    }
  }
  return true
}

fn is_number(t: Str) -> Bool {
  if t.starts_with("-") {
    return all_in(t.slice(1, t.len()), "0123456789")
  }
  return all_in(t, "0123456789")
}

fn is_name(t: Str) -> Bool {
  return all_in(t, "abcdefghijklmnopqrstuvwxyz")
}

fn is_term(t: Str) -> Bool {
  return is_number(t) or is_name(t)
}

fn line_ok(tokens: List[Str]) -> Bool {
  let count = tokens.len()
  if count < 3 or count % 2 == 0 {
    return false
  }
  if not is_name(tokens.get_or(0, "")) {
    return false
  }
  if tokens.get_or(1, "") != "=" {
    return false
  }
  if not is_term(tokens.get_or(2, "")) {
    return false
  }
  var k = 3
  while k < count {
    let op = tokens.get_or(k, "")
    if op != "+" and op != "-" {
      return false
    }
    if not is_term(tokens.get_or(k + 1, "")) {
      return false
    }
    k = k + 2
  }
  return true
}

fn term_value(t: Str, vars: Map[Str, Int]) -> Result[Int, Str] {
  if is_number(t) {
    return Ok(t.to_int().unwrap_or(0))
  }
  return vars.get(t).ok_or("undefined " + t)
}

fn eval_line(tokens: List[Str], vars: Map[Str, Int]) -> Result[Int, Str] {
  var acc = term_value(tokens.get_or(2, ""), vars)?
  var k = 3
  while k < tokens.len() {
    let v = term_value(tokens.get_or(k + 1, ""), vars)?
    if tokens.get_or(k, "") == "+" {
      acc = acc + v
    } else {
      acc = acc - v
    }
    k = k + 2
  }
  return Ok(acc)
}

pub fn run_vars(lines: List[Str]) -> Result[Map[Str, Int], Str] {
  var vars: Map[Str, Int] = Map {}
  for line in lines {
    let tokens = line.split(" ")
    if not line_ok(tokens) {
      return Err("syntax error")
    }
    let result = eval_line(tokens, vars)?
    vars = vars.set(tokens.get_or(0, ""), result)
  }
  return Ok(vars)
}
